<template>
  <div class="equipment-page">
    <section class="panel model-workspace" v-loading="loading">
      <div class="model-workspace-toolbar">
        <div class="equipment-filters"><el-input v-model="keyword" clearable aria-label="搜索设备型号或工段" placeholder="搜索设备型号、工段"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-select v-model="workshopCode" clearable aria-label="筛选车间" placeholder="全部车间" @change="load"><el-option v-for="item in workshops" :key="item.code" :label="item.name" :value="item.code"/></el-select></div>
        <div class="model-workspace-tools"><div class="model-counts"><el-checkbox v-model="showInactive" @change="load">包含停用型号</el-checkbox><span>{{ filtered.length }} 个型号 · {{ relationCount }} 条备件关系</span></div><div class="equipment-page-actions"><el-button :loading="loading" aria-label="刷新设备型号" title="刷新设备型号" @click="reload"><el-icon><Refresh /></el-icon></el-button><el-button v-write v-if="$showControl(canEditAny)" @click="openImport"><el-icon><Upload /></el-icon>导入</el-button><el-button v-write v-if="$showControl(canEditAny)" type="primary" @click="openCreate"><el-icon><Plus /></el-icon>新增型号</el-button></div></div>
      </div>
      <div v-if="filtered.length" class="model-workspace-body">
        <nav class="model-navigation" aria-label="设备型号列表">
          <div class="model-navigation-title">设备型号 <span>关联备件</span></div>
          <button v-for="item in filtered" :key="item.id" type="button" class="model-nav-item" :class="{'is-selected':selectedEquipmentId===item.id}" :aria-pressed="selectedEquipmentId===item.id" @click="openDetail(item)">
            <span class="model-nav-copy"><strong>{{ item.equipmentName }} <el-tag v-if="item.status==='inactive'" size="small" type="info">已停用</el-tag></strong><small>{{ workshopName(item.workshopCode) }} · {{ item.workshopGroup || '未分工段' }}</small></span><span class="model-part-count">{{ item.partCount || 0 }}</span>
          </button>
        </nav>
        <section class="model-detail" v-loading="detailLoading" aria-label="型号关联备件">
          <template v-if="detail">
            <header class="model-detail-heading"><div><div class="model-eyebrow">{{ workshopName(detail.workshopCode) }}<span v-if="detail.workshopGroup"> / {{ detail.workshopGroup }}</span></div><h3>{{ detail.equipmentName }}</h3><p v-if="detail.notes">{{ detail.notes }}</p></div><div v-if="$showControl(canEditWorkshop(detail.workshopCode))" class="model-actions"><el-button v-write v-if="detail.status!=='inactive'" type="primary" plain @click="openLink"><el-icon><Plus /></el-icon>关联备件</el-button><el-dropdown @command="handleModelAction"><el-button v-write>管理型号<el-icon><ArrowDown /></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-write command="edit">编辑型号</el-dropdown-item><el-dropdown-item v-write command="status">{{ detail.status==='inactive'?'恢复型号':'停用型号' }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
            <div class="related-parts-heading"><strong>常用备件 <span>{{ detail.parts?.length || 0 }}</span></strong><el-input v-model="linkedKeyword" clearable aria-label="筛选关联备件" placeholder="在关联备件中查找"><template #prefix><el-icon><Search /></el-icon></template></el-input></div>
            <el-table :data="filteredLinkedParts" empty-text="暂无匹配的关联备件" class="related-parts-table">
              <el-table-column label="备件名称" min-width="220"><template #default="{row}"><div class="material-cell"><strong>{{ row.materialDesc }}</strong><span>{{ row.spec || '未填写规格' }}</span></div></template></el-table-column>
              <el-table-column prop="materialCode" label="物料编码" width="130" />
              <el-table-column label="当前库存" width="110" align="right"><template #default="{row}"><strong>{{ row.totalStock }}</strong> {{ row.unit }}</template></el-table-column>
              <el-table-column label="单台用量" width="110" align="right"><template #default="{row}">{{ row.quantityPerEquipment ?? '-' }} {{ row.unit }}</template></el-table-column>
              <el-table-column prop="notes" label="备注" min-width="140" show-overflow-tooltip />
              <el-table-column label="操作" width="205" align="right"><template #default="{row}"><el-button link type="primary" @click="viewPart(row)">库存详情</el-button><template v-if="$showControl(canEditWorkshop(detail.workshopCode))&&detail.status!=='inactive'"><el-button v-write link type="primary" @click="openRelationEdit(row)">编辑</el-button><el-button v-write link type="danger" @click="removeLink(row)">解除</el-button></template></template></el-table-column>
            </el-table>
          </template>
          <div v-else-if="detailError" class="model-inline-error"><p>型号详情加载失败</p><el-button @click="refreshDetail">重试</el-button></div>
        </section>
      </div>
      <div v-else-if="!loading" class="model-empty-state"><el-icon><SetUp /></el-icon><h3>{{ keyword || workshopCode ? '没有匹配的设备型号' : '建立型号与备件的对应关系' }}</h3><p>{{ keyword || workshopCode ? '试试其他关键词，或切换车间。' : '新增型号或导入已有台账后，即可在这里维护常用备件。' }}</p><el-button v-if="!keyword&&!workshopCode&&$showControl(canEditAny)" v-write type="primary" plain @click="openCreate"><el-icon><Plus /></el-icon>新增型号</el-button></div>
    </section>

    <el-dialog v-model="createVisible" title="新增设备型号" width="min(600px, 94vw)" destroy-on-close><el-form label-position="top"><el-form-item label="所属车间" required><el-select v-model="equipmentForm.workshopCode" style="width:100%"><el-option v-for="item in editableWorkshops" :key="item.code" :label="item.name" :value="item.code"/></el-select></el-form-item><div class="form-grid"><el-form-item label="设备型号" required><el-input v-model="equipmentForm.equipmentName" placeholder="例如：斗式提升机NE30" /></el-form-item><el-form-item label="所属工段"><el-input v-model="equipmentForm.workshopGroup" placeholder="例如：输送工段" /></el-form-item></div><el-form-item label="备注"><el-input v-model="equipmentForm.notes" type="textarea" :rows="2" /></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button v-write type="primary" :loading="saving" @click="saveEquipment">保存型号</el-button></template></el-dialog>

    <el-dialog v-model="linkVisible" title="关联常用备件" width="min(720px, 94vw)" destroy-on-close><el-input v-model="partKeyword" clearable placeholder="输入物料编码、名称或规格" @keyup.enter="resetPartSearch"><template #append><el-button :loading="partLoading" @click="resetPartSearch"><el-icon><Search /></el-icon></el-button></template></el-input><el-table :data="partCandidates" v-loading="partLoading" border max-height="300" style="margin-top:14px"><el-table-column label="备件" min-width="290"><template #default="{row}"><div class="material-cell"><strong>{{ row.materialDesc }}</strong><span>{{ row.materialCode }} · {{ row.spec || '未填写规格' }}</span></div></template></el-table-column><el-table-column label="库存" width="100" align="center"><template #default="{row}">{{ row.totalStock }} {{ row.unit }}</template></el-table-column><el-table-column label="操作" width="90" align="right"><template #default="{row}"><el-button link type="primary" @click="selectPart(row)">选择</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="partPage" :page-size="20" :total="partTotal" layout="total, prev, pager, next" @current-change="searchParts" /><template v-if="selectedPart"><div class="selected-link"><strong>{{ selectedPart.materialDesc }}</strong><el-input-number v-model="linkQuantity" :min="0" :precision="4" controls-position="right" /><span>{{ selectedPart.unit || '个' }}/台</span><el-input v-model="linkNotes" placeholder="关联备注（可选）" maxlength="300" /></div></template><template #footer><el-button @click="linkVisible=false">取消</el-button><el-button v-write type="primary" :disabled="!selectedPart" :loading="saving" @click="saveLink">确认关联</el-button></template></el-dialog>

    <el-dialog v-model="editModelVisible" title="编辑设备型号" width="min(560px,94vw)" destroy-on-close>
      <el-form label-position="top"><el-form-item label="设备型号" required><el-input v-model="modelEdit.equipmentName" maxlength="150" /></el-form-item><el-form-item label="所属工段"><el-input v-model="modelEdit.workshopGroup" maxlength="100" /></el-form-item><el-form-item label="备注"><el-input v-model="modelEdit.notes" type="textarea" :rows="3" maxlength="500" /></el-form-item></el-form>
      <template #footer><el-button @click="editModelVisible=false">取消</el-button><el-button v-write type="primary" :loading="saving" @click="saveModelEdit">保存</el-button></template>
    </el-dialog>
    <el-dialog v-model="relationEditVisible" title="编辑备件关系" width="min(560px,94vw)" destroy-on-close>
      <p>{{ relationEdit.name }}</p><el-form label-position="top"><el-form-item label="单台用量"><el-input-number v-model="relationEdit.quantityPerEquipment" :min="0" :precision="4" /></el-form-item><el-form-item label="备注"><el-input v-model="relationEdit.notes" type="textarea" :rows="3" maxlength="300" /></el-form-item></el-form>
      <template #footer><el-button @click="relationEditVisible=false">取消</el-button><el-button v-write type="primary" :loading="saving" @click="saveRelationEdit">保存</el-button></template>
    </el-dialog>
    <el-dialog v-model="importVisible" title="批量导入设备型号与备件关系" width="min(760px,94vw)" destroy-on-close>
      <el-form label-position="top"><el-form-item label="所属车间" required><div class="import-scope"><el-select v-model="importWorkshopCode" @change="importPreview=null"><el-option v-for="item in editableWorkshops" :key="item.code" :label="item.name" :value="item.code"/></el-select><el-button :loading="templateLoading" @click="downloadTemplate">下载模板</el-button></div><small class="scope-tip">整批校验通过后才会写入；任一错误都不会产生部分数据。</small></el-form-item><el-form-item label="Excel 文件（.xlsx）" required><el-upload v-write ref="importUploadRef" drag :auto-upload="false" :limit="1" accept=".xlsx" :on-change="file=>{importFile=file.raw||null;importPreview=null}" :on-remove="()=>{importFile=null;importPreview=null}" style="width:100%"><el-icon class="el-icon--upload"><UploadFilled /></el-icon><div class="el-upload__text">拖入文件，或<em>点击选择</em></div></el-upload></el-form-item></el-form>
      <div v-if="importPreview" class="import-result" :class="{'has-errors':importPreview.errorCount}"><div class="import-result-head"><strong>{{ importPreview.errorCount?`发现 ${importPreview.errorCount} 个问题`:`校验通过：${importPreview.modelCount} 个型号、${importPreview.relationCount} 条关系` }}</strong><el-button v-if="importPreview.errorCount" type="warning" plain :loading="errorReportDownloading" @click="downloadErrorReport">下载错误修正台账</el-button></div><el-table v-if="importPreview.errors?.length" :data="importPreview.errors" size="small" border max-height="230"><el-table-column prop="row" label="行" width="60"/><el-table-column prop="field" label="字段" width="110"/><el-table-column prop="reason" label="原因" min-width="210"/><el-table-column prop="suggestion" label="修改建议" min-width="180"/></el-table></div>
      <template #footer><el-button @click="importVisible=false">取消</el-button><el-button v-write :loading="previewing" @click="previewImportFile">校验文件</el-button><el-button v-write type="primary" :loading="saving" :disabled="!importPreview||importPreview.errorCount>0" @click="applyImport">确认导入</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import { createEquipment, downloadEquipmentImportErrorReport, downloadEquipmentImportTemplate, getEquipment, getEquipmentDetail, getParts, importEquipment, linkEquipmentPart, previewEquipmentImport, unlinkEquipmentPart, updateEquipment, updateEquipmentPart } from '../api'
import { inventoryRouteQuery } from '../utils/inventory-scope.mjs'
import { canEditAnyWorkshop, canEditWorkshop, userWorkshopCode } from '../auth'
const route=useRoute()
const router=useRouter(),showInactive=ref(false),editModelVisible=ref(false),relationEditVisible=ref(false)
const modelEdit=reactive({id:'',equipmentName:'',workshopGroup:'',notes:''})
const relationEdit=reactive({id:'',equipmentId:'',name:'',quantityPerEquipment:null,notes:''})
const loading=ref(false),equipment=ref([]),keyword=ref(''),detail=ref(null),createVisible=ref(false),linkVisible=ref(false),saving=ref(false),partKeyword=ref(''),partLoading=ref(false),partCandidates=ref([]),selectedPart=ref(null),linkQuantity=ref(1)
const selectedEquipmentId=ref(''),detailLoading=ref(false),detailError=ref(false),linkedKeyword=ref('')
const partPage=ref(1),partTotal=ref(0),linkNotes=ref('')
let partRequest=0,detailRequest=0, listRequest=0
const importVisible=ref(false),importWorkshopCode=ref(''),importFile=ref(null),importPreview=ref(null),importUploadRef=ref(null),previewing=ref(false),templateLoading=ref(false),errorReportDownloading=ref(false)
const workshops=[{code:'raw_grain',name:'原粮车间'},{code:'qu_making',name:'制曲车间'},{code:'brewing',name:'酿酒车间'}]
const canEditAny=canEditAnyWorkshop(),ownWorkshop=userWorkshopCode()||'raw_grain'
const editableWorkshops=workshops.filter(item=>canEditWorkshop(item.code))
const workshopCode=ref(['raw_grain','qu_making','brewing'].includes(String(route.query.workshopCode||''))?String(route.query.workshopCode):'')
const equipmentForm=reactive({workshopCode:ownWorkshop,equipmentName:'',workshopGroup:'',notes:''})
const filtered=computed(()=>{const key=keyword.value.trim().toLowerCase();return key?equipment.value.filter(item=>[item.equipmentName,item.workshopGroup].some(v=>String(v||'').toLowerCase().includes(key))):equipment.value})
const relationCount=computed(()=>filtered.value.reduce((sum,item)=>sum+Number(item.partCount||0),0))
const filteredLinkedParts=computed(()=>{const key=linkedKeyword.value.trim().toLowerCase();return (detail.value?.parts||[]).filter(item=>!key||[item.materialCode,item.materialDesc,item.spec].some(value=>String(value||'').toLowerCase().includes(key)))})
function workshopName(code){return workshops.find(item=>item.code===code)?.name||code||'未分车间'}
async function load(){const request=++listRequest;loading.value=true;try{const result=await getEquipment({workshopCode:workshopCode.value||undefined,status:showInactive.value?'all':'active'});if(request===listRequest)equipment.value=result.data||[]}finally{if(request===listRequest)loading.value=false}}
async function refreshDetail(){if(selectedEquipmentId.value)await openDetail({id:selectedEquipmentId.value},false)}
async function reload(){await load();await refreshDetail()}
async function openDetail(item,resetSearch=true){const request=++detailRequest;selectedEquipmentId.value=item.id;detail.value=null;detailLoading.value=true;detailError.value=false;if(resetSearch)linkedKeyword.value='';try{const result=await getEquipmentDetail(item.id);if(request===detailRequest)detail.value=result.data}catch{if(request===detailRequest)detailError.value=true}finally{if(request===detailRequest)detailLoading.value=false}}
watch(filtered,items=>{if(!items.some(item=>item.id===selectedEquipmentId.value)){if(items.length)openDetail(items[0]);else{detailRequest++;selectedEquipmentId.value='';detail.value=null;detailLoading.value=false}}})
function openCreate(){Object.assign(equipmentForm,{workshopCode:canEditWorkshop(workshopCode.value)?workshopCode.value:(editableWorkshops[0]?.code||ownWorkshop),equipmentName:'',workshopGroup:'',notes:''});createVisible.value=true}
async function handleModelAction(command){const item=detail.value;if(!item||!canEditWorkshop(item.workshopCode))return;if(command==='edit'){Object.assign(modelEdit,{id:item.id,equipmentName:item.equipmentName,workshopGroup:item.workshopGroup||'',notes:item.notes||''});editModelVisible.value=true;return}const restoring=item.status==='inactive';try{await ElMessageBox.confirm(restoring?'恢复后可继续维护型号与备件关系。':'停用后从默认列表隐藏，已有备件关系会保留。',restoring?'恢复型号':'停用型号',{type:'warning'})}catch{return}await updateEquipment(item.id,{status:restoring?'active':'inactive'});ElMessage.success(restoring?'型号已恢复':'型号已停用');await reload()}
async function saveModelEdit(){if(!modelEdit.equipmentName.trim())return ElMessage.warning('请填写设备型号');saving.value=true;try{await updateEquipment(modelEdit.id,{equipmentName:modelEdit.equipmentName.trim(),workshopGroup:modelEdit.workshopGroup,notes:modelEdit.notes});editModelVisible.value=false;await reload();ElMessage.success('型号已更新')}finally{saving.value=false}}
function viewPart(row){router.push({path:'/inventory',query:inventoryRouteQuery({workshopCode:detail.value.workshopCode,searchKeyword:row.materialCode})})}
function openRelationEdit(row){Object.assign(relationEdit,{id:row.id,equipmentId:detail.value.id,name:row.materialDesc,quantityPerEquipment:row.quantityPerEquipment==null?null:Number(row.quantityPerEquipment),notes:row.notes||''});relationEditVisible.value=true}
async function saveRelationEdit(){saving.value=true;try{await updateEquipmentPart(relationEdit.equipmentId,relationEdit.id,{quantityPerEquipment:relationEdit.quantityPerEquipment,notes:relationEdit.notes});relationEditVisible.value=false;await refreshDetail();ElMessage.success('备件关系已更新')}finally{saving.value=false}}
async function saveEquipment(){if(!equipmentForm.workshopCode||!equipmentForm.equipmentName.trim())return ElMessage.warning('请选择车间并填写设备型号');saving.value=true;try{await createEquipment({...equipmentForm});ElMessage.success('设备型号已创建');createVisible.value=false;workshopCode.value=equipmentForm.workshopCode;load()}finally{saving.value=false}}
function openLink(){partKeyword.value='';partCandidates.value=[];selectedPart.value=null;linkQuantity.value=1;linkNotes.value='';partPage.value=1;partTotal.value=0;linkVisible.value=true;searchParts()}
function resetPartSearch(){partPage.value=1;searchParts()}
async function searchParts(){const token=++partRequest;partLoading.value=true;try{const result=await getParts({page:partPage.value,pageSize:20,searchKeyword:partKeyword.value,workshopCode:detail.value?.workshopCode});if(token!==partRequest)return;partCandidates.value=result.data||[];partTotal.value=result.total||0}finally{if(token===partRequest)partLoading.value=false}}
function selectPart(row){selectedPart.value=row}
async function saveLink(){saving.value=true;try{await linkEquipmentPart(detail.value.id,{inventoryId:selectedPart.value._id,quantityPerEquipment:linkQuantity.value,notes:linkNotes.value});ElMessage.success('备件关系已建立');linkVisible.value=false;await Promise.all([refreshDetail(),load()])}finally{saving.value=false}}
async function removeLink(row){const model=detail.value;try{await ElMessageBox.confirm(`确认解除“${model.equipmentName}”与“${row.materialCode} ${row.materialDesc}”的关系吗？`,'解除备件关系',{type:'warning',confirmButtonText:'确认解除'})}catch{return}await unlinkEquipmentPart(model.id,row.id);ElMessage.success('备件关系已解除');await Promise.all([refreshDetail(),load()])}
function saveBlob(blob,name){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}
function openImport(){importWorkshopCode.value=canEditWorkshop(workshopCode.value)?workshopCode.value:(editableWorkshops[0]?.code||ownWorkshop);importFile.value=null;importPreview.value=null;importUploadRef.value?.clearFiles();importVisible.value=true}
async function downloadTemplate(){templateLoading.value=true;try{const blob=await downloadEquipmentImportTemplate();saveBlob(blob,'设备型号与备件关系导入模板.xlsx')}finally{templateLoading.value=false}}
function importFormData(){const data=new FormData();data.append('workshopCode',importWorkshopCode.value);data.append('file',importFile.value);return data}
async function previewImportFile(){if(!importWorkshopCode.value||!importFile.value)return ElMessage.warning('请选择车间和 .xlsx 文件');previewing.value=true;try{const result=await previewEquipmentImport(importFormData());importPreview.value=result.data;ElMessage[result.data?.errorCount?'warning':'success'](result.msg)}finally{previewing.value=false}}
async function downloadErrorReport(){errorReportDownloading.value=true;try{const blob=await downloadEquipmentImportErrorReport(importFormData());saveBlob(blob,`设备型号与备件关系-错误修正台账-${Date.now()}.xlsx`)}finally{errorReportDownloading.value=false}}
async function applyImport(){if(!importPreview.value||importPreview.value.errorCount)return ElMessage.warning('请先校验并修正全部问题');saving.value=true;try{const result=await importEquipment(importFormData());ElMessage.success(result.msg);importVisible.value=false;workshopCode.value=importWorkshopCode.value;await load()}finally{saving.value=false}}
onMounted(async()=>{await load();if(route.query.equipmentId||route.query.id){const target=equipment.value.find(item=>String(item.id)===String(route.query.equipmentId||route.query.id));if(target)await openDetail(target)}})
</script>

<style scoped>
.model-actions{display:flex;gap:8px;flex-wrap:wrap;flex:none}.model-counts{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.model-counts>span{white-space:nowrap}.model-workspace-tools,.equipment-page-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}.equipment-page-actions .el-button+.el-button{margin-left:0}
.model-workspace{overflow:hidden;border-radius:16px;box-shadow:0 5px 22px #17203304}.model-workspace-toolbar{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:14px 18px;border-bottom:1px solid var(--line)}.equipment-filters{display:flex;gap:10px;flex:1 1 42%;min-width:280px}.equipment-filters .el-input{flex:1;min-width:180px}.equipment-filters .el-select{width:160px;flex:none}.model-counts{color:var(--muted);font-size:12px;white-space:nowrap}.model-counts i{margin:0 8px;font-style:normal;color:#c0c6d0}.model-workspace-body{display:grid;grid-template-columns:310px minmax(0,1fr);min-height:470px}.model-navigation{padding:14px 10px;background:#fafbfc;border-right:1px solid var(--line);max-height:640px;overflow-y:auto}.model-navigation-title{display:flex;justify-content:space-between;padding:0 12px 12px;font-size:12px;color:var(--muted)}.model-nav-item{width:100%;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:15px 12px;margin-bottom:5px;text-align:left;border:1px solid transparent;border-radius:10px;background:transparent;color:var(--ink);cursor:pointer}.model-nav-item:hover{background:#fff;border-color:var(--line)}.model-nav-item.is-selected{background:#fff;border-color:#eec2c6;box-shadow:inset 3px 0 var(--brand)}.model-nav-item:focus-visible{outline:2px solid var(--brand);outline-offset:1px}.model-nav-copy{min-width:0}.model-nav-copy strong{display:block;overflow-wrap:anywhere;font-size:14px;line-height:1.5}.model-nav-copy small{display:block;margin-top:5px;color:var(--muted);line-height:1.5}.model-part-count{flex:none;min-width:28px;text-align:center;border-radius:6px;padding:4px;background:#eef0f4;color:#536174;font-size:12px;font-weight:700}.is-selected .model-part-count{color:var(--brand);background:var(--brand-soft)}.model-detail{min-width:0;padding:24px}.model-detail-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:25px}.model-detail-heading>div{min-width